sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {
        if (isLoading) {
            if (g_form.getValue('swift_linking_reference_id')!= '' && g_form.getValue('tran_reference_for_swift_linking')!='') {
                g_form.setDisplay('swift_linking_reference_id', true);
                g_form.setDisplay('tran_reference_for_swift_linking', true);
            }
        }
        return;
    }
    var trigger_by = g_scratchpad.triggerby;
    var code = trigger_by.slice(0, 2);
    if (newValue == 'Trade actioned in GHSS' && code == 'MT') {
        g_form.setMandatory('tran_reference_for_swift_linking', true);
    } else {
        g_form.setMandatory('tran_reference_for_swift_linking', false);
    }
}
